// tests/view/uiText.test.ts
// UiText against injected fetch fakes + the REAL extracted strings.json
// (public/assets/ui — generated by tools/assets/extract_ui_text.py from the
// original Q4.TextDatabase tables). Covers: load/parse/failure, t() lookup
// semantics, wave/difficulty key construction (verified D2 format), hudStrings
// mapping, menu labels, graceful degradation with an empty table.

import { describe, it, expect } from 'vitest';
import {
  loadStrings,
  t,
  stripIcons,
  waveCallKey,
  difficultyKey,
  waveAccentKey,
  hudStrings,
  menuStrings,
  type StringTable,
  type HudState,
} from '../../src/view/ui/UiText';
import realStrings from '../../public/assets/ui/strings.json';

const table = realStrings as StringTable;

function fetchReturning(body: string): (url: string) => Promise<string> {
  return async () => body;
}

const state: HudState = {
  coins: 450, gems: 3, wave: 3, waveCount: 10, chibis: 12, chibiTotal: 20,
};

describe('loadStrings', () => {
  it('fetches strings.json under baseUrl and parses it', async () => {
    const urls: string[] = [];
    const fetchImpl = async (url: string) => {
      urls.push(url);
      return JSON.stringify({ tl_stage_001: 'STAGE 1', tl_result_003: 'Coins' });
    };
    const loaded = await loadStrings('/x/ui/', fetchImpl);
    expect(urls).toEqual(['/x/ui/strings.json']);
    expect(loaded.tl_stage_001).toBe('STAGE 1');
    expect(loaded.tl_result_003).toBe('Coins');
  });

  it('resolves {} when the fetch rejects (never throws)', async () => {
    const loaded = await loadStrings('/assets/ui/', async () => {
      throw new Error('404');
    });
    expect(loaded).toEqual({});
  });

  it('resolves {} on malformed JSON or non-object payloads', async () => {
    expect(await loadStrings(undefined, fetchReturning('{oops'))).toEqual({});
    expect(await loadStrings(undefined, fetchReturning('[1,2]'))).toEqual({});
    expect(await loadStrings(undefined, fetchReturning('null'))).toEqual({});
  });

  it('drops non-string values defensively', async () => {
    const loaded = await loadStrings(undefined, fetchReturning(
      JSON.stringify({ a: 'ok', b: 7, c: null, d: { x: 1 }, e: '' }),
    ));
    expect(loaded).toEqual({ a: 'ok', e: '' });
  });
});

describe('t()', () => {
  it('returns the table value for a present key', () => {
    expect(t(table, 'tl_difficulty_003')).toBe('Mayhem');
  });

  it('missing key -> fallback, or the key itself when no fallback given', () => {
    expect(t(table, 'tl_nope_999', 'fallback')).toBe('fallback');
    expect(t(table, 'tl_nope_999')).toBe('tl_nope_999');
    expect(t({}, 'tl_stage_001', 'STAGE 1')).toBe('STAGE 1');
  });

  it('empty-string value falls back (original tables have empty rows)', () => {
    expect(t({ k: '' }, 'k', 'fb')).toBe('fb');
    expect(t({ k: '' }, 'k')).toBe('k');
  });
});

describe('key construction (verified formats)', () => {
  it('waveCallKey zero-pads to D2 like StartCallMenuController.Show', () => {
    expect(waveCallKey(0)).toBe('tl_wave_call_00');
    expect(waveCallKey(1)).toBe('tl_wave_call_01');
    expect(waveCallKey(10)).toBe('tl_wave_call_10');
    expect(t(table, waveCallKey(0))).toBe('WAVE START');
    expect(t(table, waveCallKey(3))).toBe('WAVE 3');
  });

  it('difficultyKey maps Fun/Tricky/Mayhem (not Easy/Medium/Hard)', () => {
    expect(difficultyKey(0)).toBe('tl_difficulty_001');
    expect(difficultyKey(1)).toBe('tl_difficulty_002');
    expect(difficultyKey(2)).toBe('tl_difficulty_003');
    expect(difficultyKey(-1)).toBe('tl_multiplay_011');
    expect(t(table, difficultyKey(0))).toBe('Fun');
    expect(t(table, difficultyKey(1))).toBe('Tricky');
    expect(t(table, difficultyKey(2))).toBe('Mayhem');
  });

  it('waveAccentKey matches the serialized StartCallMenuController fields', () => {
    expect(t(table, waveAccentKey('first'))).toBe('Here they come!');
    expect(t(table, waveAccentKey('normal'))).toBe('More incoming!');
    expect(t(table, waveAccentKey('final'))).toBe('Last push!');
    expect(t(table, waveAccentKey('cleared'))).toBe('You made it!');
  });
});

describe('hudStrings', () => {
  it('maps stage/area/difficulty header keys for 3d_stage_001', () => {
    const h = hudStrings(table, state);
    expect(h.stage).toBe('STAGE 1');
    expect(h.area).toBe('Pockulu Forest');
    expect(h.difficulty).toBe('Fun');
    expect(hudStrings(table, { ...state, difficulty: 2 }).difficulty).toBe('Mayhem');
  });

  it('maps coin/gem/chibi labels and counts to original wording', () => {
    const h = hudStrings(table, state);
    expect(h.coinLabel).toBe('Coins');       // tl_result_003
    expect(h.gemLabel).toBe('Gems');         // tl_result_005
    expect(h.chibiLabel).toBe('Chibis Saved'); // tl_result_008
    expect(h.coins).toBe('450');
    expect(h.gems).toBe('3');
    expect(h.chibis).toBe('12/20');          // GameInfoController "/{0}" format
  });

  it('renders the wave call and best-effort progress composite', () => {
    const h = hudStrings(table, state);
    expect(h.wave).toBe('WAVE 3');
    expect(h.waveProgress).toBe('WAVE 3 / 10');
    expect(hudStrings(table, { ...state, wave: 0 }).wave).toBe('WAVE START');
  });

  it('outcome banners: CLEAR / Perfect! / GAME OVER, null while playing', () => {
    expect(hudStrings(table, state).bannerTitle).toBeNull();
    const cleared = hudStrings(table, { ...state, outcome: 'cleared' });
    expect(cleared.bannerTitle).toBe('CLEAR');
    expect(cleared.bannerSub).toBe('Chibis Saved 12/20');
    const perfect = hudStrings(table, { ...state, outcome: 'cleared', perfect: true, chibis: 20 });
    expect(perfect.bannerTitle).toBe('Perfect!');
    expect(perfect.bannerSub).toBe('Chibis Saved 20/20');
    const over = hudStrings(table, { ...state, outcome: 'gameover' });
    expect(over.bannerTitle).toBe('GAME OVER');
    expect(over.bannerSub).toBe('Waves Cleared 2 / 10');
  });

  it('degrades gracefully with an empty table (fallbacks mirror verified text)', () => {
    const h = hudStrings({}, { ...state, outcome: 'cleared', perfect: true });
    expect(h.stage).toBe('STAGE 1');
    expect(h.difficulty).toBe('Fun');
    expect(h.coinLabel).toBe('Coins');
    expect(h.wave).toBe('WAVE 3');
    expect(h.bannerTitle).toBe('Perfect!');
    expect(() => hudStrings({}, state)).not.toThrow();
  });
});

describe('menuStrings + icon tokens', () => {
  it('pause/options labels match the original tables', () => {
    const m = menuStrings(table);
    expect(m.pauseTitle).toBe('PAUSE');
    expect(m.resume).toBe('Resume');
    expect(m.retry).toBe('Retry');
    expect(m.stageSelect).toBe('Stage Select');
    expect(m.soundEffects).toBe('Sound Effects');
    expect(m.on).toBe('ON');
    expect(m.off).toBe('OFF');
    expect(m.pressAnyButton).toBe('Press any button');
    // empty table still yields usable labels
    expect(menuStrings({}).resume).toBe('Resume');
  });

  it('stripIcons removes original {icon}/{param} placeholders', () => {
    expect(stripIcons('Jump {jump}!\nJump {jump}!')).toBe('Jump !\nJump !');
    expect(stripIcons('Use Rainbow\nFragments {c_rainbow_01}\nto open paths!'))
      .toBe('Use Rainbow\nFragments \nto open paths!');
    expect(stripIcons(t(table, 'tl_mini_dialog_text_005'))).toBe('Build towers\nto defeat\nmonsters!');
  });
});

describe('extracted strings.json sanity', () => {
  it('contains the verified stage-1 gameplay keys with original English text', () => {
    expect(table.tl_wave_call_22).toBe('Wave Cleared!');
    expect(table.tl_in_game_003).toBe('CLEAR');
    expect(table.tl_gameover_001).toBe('GAME OVER');
    expect(table.tl_result_010).toBe('Perfect!');
    expect(table.tl_tower_name_007).toBe('Arrow');
    expect(table.tl_dialog_text_016).toContain('Protect the last remaining one!');
    // filtered out: JP placeholder towers, empty rows, font atlas, sign names
    expect(table.tl_tower_name_013).toBeUndefined();
    expect(table.tl_wave_call_21).toBeUndefined();
    expect(table.tl_global_001).toBeUndefined();
    expect(table.tl_sign_name_001).toBeUndefined();
  });
});
